const paths = [
  "/Users/peytonmontei/.agents/skills/superpowers/brainstorming/SKILL.md",
  "/Users/peytonmontei/.agents/skills/superpowers/writing-plans/SKILL.md",
  "/Users/peytonmontei/.agents/skills/superpowers/verification-before-completion/SKILL.md"
];
const rs = await Promise.all(paths.map(p => tools.exec_command({cmd:`sed -n '1,1200p' '${p}'`,workdir:"/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review",yield_time_ms:10000,max_output_tokens:30000})));
for (let i=0;i<rs.length;i++) text(`FILE ${paths[i]}\n${rs[i].output}`);

const wd="/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review";
const cmds=[
 ["entire-status","entire status"],
 ["git-status","git status --short --branch"],
 ["git-status-full","git status"],
 ["recent","git log --oneline --decorate -8"],
 ["remotes","git remote -v"],
 ["merge-head","git rev-parse -q --verify MERGE_HEAD"],
 ["rebase-head","git rev-parse -q --verify REBASE_HEAD"],
 ["cherry-pick-head","git rev-parse -q --verify CHERRY_PICK_HEAD"],
 ["pr","gh pr view 2013 --repo entireio/cli --json number,title,state,isDraft,baseRefName,headRefName,headRepositoryOwner,headRepository,mergeStateStatus,mergeable,url,author,statusCheckRollup"]
];
const rs=await Promise.all(cmds.map(async ([name,cmd])=>[name,await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:20000})]));
for (const [name,r] of rs) text(`${name} (exit ${r.exit_code}):\n${r.output}`);

const r=await tools.exec_command({
  cmd:"gh pr view 2013 --repo entireio/cli --json number,title,state,isDraft,baseRefName,headRefName,headRepositoryOwner,headRepository,mergeStateStatus,mergeable,url,author,statusCheckRollup",
  workdir:"/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review",
  yield_time_ms:10000,
  max_output_tokens:20000,
  sandbox_permissions:"require_escalated",
  justification:"May I access GitHub to inspect PR #2013’s exact base/head branches and conflict status?",
  prefix_rule:["gh","pr","view"]
});
text(r.output);

const wd="/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review";
const rs=await Promise.all([
  tools.exec_command({cmd:"git worktree list --porcelain",workdir:wd,yield_time_ms:10000,max_output_tokens:20000}),
  tools.exec_command({cmd:"git branch -vv --all",workdir:wd,yield_time_ms:10000,max_output_tokens:20000}),
  tools.exec_command({cmd:"git fetch origin main feat/session-identity-linking",workdir:wd,yield_time_ms:30000,max_output_tokens:20000})
]);
text(`worktrees:\n${rs[0].output}`);
text(`branches:\n${rs[1].output}`);
text(`fetch (exit ${rs[2].exit_code}):\n${rs[2].output}`);

const wd="/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review";
const cmds=[
 ["worktree-owner","git worktree list --porcelain"],
 ["tips","git rev-parse HEAD origin/main origin/feat/session-identity-linking"],
 ["merge-base","git merge-base origin/main origin/feat/session-identity-linking"],
 ["head-log","git log --oneline --decorate origin/main..origin/feat/session-identity-linking"],
 ["base-log","git log --oneline --decorate origin/feat/session-identity-linking..origin/main"],
 ["files","git diff --name-status origin/main...origin/feat/session-identity-linking"],
 ["stat","git diff --stat origin/main...origin/feat/session-identity-linking"],
 ["merge-tree","git merge-tree --write-tree origin/feat/session-identity-linking origin/main"]
];
const rs=await Promise.all(cmds.map(async ([name,cmd])=>[name,await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:30000})]));
for (const [name,r] of rs) {
  let out=r.output;
  if (name==="worktree-owner") {
    const lines=out.split("\n"); const hits=[];
    for (let i=0;i<lines.length;i++) if (lines[i].includes("feat/session-identity-linking")) hits.push(lines.slice(Math.max(0,i-2),Math.min(lines.length,i+2)).join("\n"));
    out=hits.length?hits.join("\n---\n"):"not checked out in another worktree";
  }
  text(`${name} (exit ${r.exit_code}):\n${out}`);
}

const r=await tools.exec_command({
  cmd:"git merge-tree cdd41d4b5c73cd08ac30390166da32cec9cd0e1b 50e6dcc863abf53aeb8a6fd4d24025ff42f39e98 faf63b89dd5ceb0ed3b9a01ebaaa02cbb528bacf",
  workdir:"/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review",
  yield_time_ms:10000,
  max_output_tokens:40000
});
text(`exit ${r.exit_code}\n${r.output}`);

const r=await tools.exec_command({
  cmd:"git merge-tree cdd41d4b5c73cd08ac30390166da32cec9cd0e1b 50e6dcc863abf53aeb8a6fd4d24025ff42f39e98 faf63b89dd5ceb0ed3b9a01ebaaa02cbb528bacf | rg -A3 '^(changed in both|added in both|removed in remote|removed in local)'",
  workdir:"/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/new-pr-review",
  yield_time_ms:10000,
  max_output_tokens:20000
});
